package com.yeyamo_mobile.api.recommendation_service.infrastructure.persistence;import java.time.Instant;import java.util.*;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface CandidateRepository extends JpaRepository<CandidateEntity,String>{@Modifying@Query("update CandidateEntity c set c.popularity=case when c.popularity+:delta<0 then 0 else c.popularity+:delta end,c.updatedAt=:now where c.sourceId=:id")int adjust(@Param("id")String id,@Param("delta")double delta,@Param("now")Instant now);List<CandidateEntity>findByActiveTrueOrderByPopularityDescPublishedAtDesc(Pageable page);@Query(value="select c.category_code,sum(s.weight) from recommendation_user_signals s join recommendation_candidates c on c.source_id=s.source_id where s.user_id=:user and c.category_code is not null and s.weight>0 group by c.category_code",nativeQuery=true)List<Object[]>affinities(@Param("user")String user);}
